S={(0,2),(1,1),(1,3),(2,0),(2,1),(2,3)}
# dihedral coordinate transformations on square then normalize
import itertools
pts=[(r,c) for r,c in S]
def transforms(shape):
 out=[]
 for k in range(4):
  for refl in [False,True]:
   arr=[]
   for r,c in shape:
    if refl:c=-c
    for _ in range(k):r,c=c,-r
    arr.append((r,c))
   mr=min(r for r,c in arr);mc=min(c for r,c in arr)
   norm=frozenset((r-mr,c-mc) for r,c in arr)
   if norm not in [x[0] for x in out]: out.append((norm,(k,refl)))
 return out
trs=transforms(S)
objs={'8':[(1,23),(2,22),(3,22)],'7':[(19,11),(20,12)],'5':[(9,25),(10,24),(10,25)],'6':[(11,5),(12,5),(12,7)],'3':[(11,15),(12,16),(13,16)],'2':[(21,22),(21,23)],'9':[(22,5),(23,3)]}
for name,obj in objs.items():
 fits=[]
 for shape,ori in trs:
  for r0 in range(min(r for r,c in obj)-4,min(r for r,c in obj)+1):
   for c0 in range(min(c for r,c in obj)-4,min(c for r,c in obj)+1):
    placed={(r0+r,c0+c) for r,c in shape}
    if set(obj)<=placed:fits.append((ori,(r0,c0),placed))
 print(name,[(ori,off) for ori,off,_ in fits])

